class Solution:
    def findLexSmallestString(self, s: str, a: int, b: int) -> str:
        q, lookup, result = collections.deque([s]), {s}, s
        while q:
            curr = q.popleft()
            if curr < result:
                result = curr
            add_a = list(curr)    
            for i, c in enumerate(add_a):
                if i%2:
                    add_a[i] = str((int(c)+a) % 10)
            add_a = "".join(add_a)        
            if add_a not in lookup:
                lookup.add(add_a)
                q.append(add_a)
            rotate_b = curr[b:] + curr[:b]
            if rotate_b not in lookup:
                lookup.add(rotate_b)
                q.append(rotate_b)
        return result

class Solution(object):
    def bestTeamScore(self, scores, ages):
        l = len(scores)
        mapped = [[ages[i], scores[i]] for i in range(l)]
        mapped = sorted(mapped, key = lambda x : (x[0], x[1]))
        dp = [i[1] for i in mapped]

        for i in range(l):
            for j in range(0, i):
                if mapped[j][1] <= mapped[i][1]:
                    dp[i] = max(dp[i], mapped[i][1] + dp[j])
                elif mapped[i][0] == mapped[j][0]:
                    dp[i] = max(dp[i], mapped[i][1] + dp[j])

        return max(dp)

